// Chapter 9 — authorised users only.
// Replace with your own numeric Telegram user ID(s).
const ALLOWED = [111111111]; // <-- your Telegram user ID
const ALLOWED_COMMANDS = ['/task'];

const msg = $input.first().json.message || {};
const fromId = msg.from?.id;
const chatId = msg.chat?.id;
const text = (msg.text || '').trim();

if (!fromId || !chatId) return [];
if (!ALLOWED.includes(fromId)) {
  return [{ json: { denied: true, chatId, reply: '🚫 This bot is private.' } }];
}

if (!text.startsWith('/task')) {
  return [{ json: { denied: true, chatId, reply: 'Send /task <description> to plan work.' } }];
}

return [{ json: { allowed: true, chatId, request: text.replace(/^\/task\s*/i, '').trim() } }];

// Chapter 4 validation rule.
const ALLOWED_PRIORITY = ['High', 'Medium', 'Low'];
const ALLOWED_OWNER = ['You', 'Content Agent', 'Research Agent'];

const raw = $input.first().json?.message?.content || '';

function extractJson(text) {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const body = fenced ? fenced[1] : text;
  const start = body.search(/[[{]/);
  if (start === -1) throw new Error('No JSON found');
  const open = body[start];
  const close = open === '{' ? '}' : ']';
  let depth = 0, inString = false, escaped = false;
  for (let i = start; i < body.length; i++) {
    const ch = body[i];
    if (inString) {
      if (escaped) escaped = false;
      else if (ch === '\\') escaped = true;
      else if (ch === '"') inString = false;
      continue;
    }
    if (ch === '"') inString = true;
    else if (ch === open) depth++;
    else if (ch === close && --depth === 0) return JSON.parse(body.slice(start, i + 1));
  }
  throw new Error('Incomplete JSON');
}

let tasks = [];
let needsReview = false;
try {
  const payload = extractJson(raw);
  tasks = (payload.tasks || []).slice(0, 5).map((t) => ({
    task: String(t.task || '').trim(),
    priority: ALLOWED_PRIORITY.includes(t.priority) ? t.priority : 'Medium',
    owner: ALLOWED_OWNER.includes(t.owner) ? t.owner : 'You',
    deadline: /^\d{4}-\d{2}-\d{2}$/.test(String(t.deadline || '')) ? t.deadline : '',
    status: 'Pending',
    notes: String(t.notes || '').slice(0, 300),
  })).filter((t) => t.task);
  if (!tasks.length) needsReview = true;
} catch (e) {
  needsReview = true;
}

if (!tasks.length) {
  tasks = [{
    task: 'Clarify request with user',
    priority: 'Medium',
    owner: 'You',
    deadline: '',
    status: 'Pending',
    notes: 'AI output was not valid JSON — needs review',
  }];
}

const chatId = $('Allow-list & parse').first().json.chatId;
const request = $('Allow-list & parse').first().json.request;
const stamp = new Date().toISOString();

return tasks.map((t, index) => ({
  json: {
    'Task ID': 'T-' + stamp.slice(0, 10).replace(/-/g, '') + '-' + String(index + 1).padStart(2, '0'),
    'Created At': stamp.slice(0, 16).replace('T', ' '),
    Request: request,
    Task: t.task,
    Priority: t.priority,
    Owner: t.owner,
    Deadline: t.deadline,
    Status: t.status,
    Notes: t.notes,
    chatId,
    needsReview,
  },
}));

